import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"六鱼","description":"","frontmatter":{"title":"六鱼","date":"2026-11-17T00:00:00.000Z","seq":6,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/六鱼.md","filePath":"blogs/声律启蒙·上卷/六鱼.md"}'),r={name:"blogs/声律启蒙·上卷/六鱼.md"};function p(l,e,_,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="六鱼" tabindex="-1">六鱼 <a class="header-anchor" href="#六鱼" aria-label="Permalink to &quot;六鱼&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">无对有，实对虚，作赋对观书。绿窗对朱户，宝马对香车。伯乐马，浩然驴，弋雁对求鱼。分金齐鲍叔，奉璧蔺相如。掷地金声孙绰赋，回文锦字窦滔书。未遇殷宗，胥靡困傅岩之筑；既逢周后，太公舍渭水之渔。</p><p class="poem-stanza">终对始，疾对徐，短褐对华裾。六朝对三国，天禄对石渠。千字策，八行书，有若对相如。花残无戏蝶，藻密有潜鱼。落叶舞风高复下，小荷浮水卷还舒。爱见人长，共服宣尼休假盖；恐彰己吝，谁知阮裕竟焚车。</p><p class="poem-stanza">麟对凤，鳖对鱼，内史对中书。犁锄对耒耜，畎浍对郊墟。犀角带，象牙梳，驷马对安车。青衣能报赦，黄耳解传书。庭畔有人持短剑，门前无客曳长裾。波浪拍船，骇舟人之水宿；峰峦绕舍，乐隐者之山居。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
